"""Exception hierarchy for microdb."""

from __future__ import annotations


class MicroDBError(Exception):
    """Base exception for all microdb errors."""


class LexError(MicroDBError):
    """Lexer error with a zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} at offset {offset}")
        self.offset: int = offset


class ParseError(MicroDBError):
    """Parser error with a zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} at offset {offset}")
        self.offset: int = offset


class SchemaError(MicroDBError):
    """Schema definition or validation error."""


class TypeMismatchError(MicroDBError):
    """Operand or argument type mismatch error."""


class UnknownColumnError(MicroDBError):
    """Referenced column does not exist."""


class AmbiguousColumnError(MicroDBError):
    """Unqualified column exists in multiple tables."""


class UnknownTableError(MicroDBError):
    """Referenced table does not exist."""


class UnknownFunctionError(MicroDBError):
    """Referenced function does not exist."""


class ArityError(MicroDBError):
    """Function called with incorrect number of arguments."""


class AggregateError(MicroDBError):
    """Illegal aggregate usage (e.g., in WHERE)."""


class GroupingError(MicroDBError):
    """Illegal select item or expression under GROUP BY."""

"""Value model, three-valued logic, comparison and arithmetic."""

from __future__ import annotations

from microdb.errors import TypeMismatchError


def type_of(v: object) -> str:
    """Return the microdb type name of a value."""
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"Unsupported value type: {type(v).__name__}")


def is_numeric(v: object) -> bool:
    """Return True for int and float, False for bool and None."""
    if isinstance(v, bool):
        return False
    return isinstance(v, (int, float))


def _ensure_boolean(v: object, name: str) -> None:
    if v is not None and not isinstance(v, bool):
        raise TypeMismatchError(
            f"Expected boolean or NULL for {name}, got {type_of(v)}"
        )


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND logic."""
    _ensure_boolean(a, "AND left operand")
    _ensure_boolean(b, "AND right operand")
    if a is False or b is False:
        return False
    if a is True and b is True:
        return True
    return None


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR logic."""
    _ensure_boolean(a, "OR left operand")
    _ensure_boolean(b, "OR right operand")
    if a is True or b is True:
        return True
    if a is False and b is False:
        return False
    return None


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT logic."""
    _ensure_boolean(a, "NOT operand")
    if a is None:
        return None
    return not a


def _check_comparable(a: object, b: object) -> None:
    if is_numeric(a) and is_numeric(b):
        return
    if isinstance(a, str) and isinstance(b, str):
        return
    if isinstance(a, bool) and isinstance(b, bool):
        return
    raise TypeMismatchError(f"Cannot compare {type_of(a)} and {type_of(b)}")


def compare_eq(a: object, b: object) -> bool | None:
    """Compare equality with SQL three-valued logic."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    """Compare less-than with SQL three-valued logic."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a < b


def arith(op: str, a: object, b: object) -> object:
    """Evaluate binary arithmetic with NULL propagation and zero division handling."""
    if a is None or b is None:
        return None
    if not is_numeric(a) or not is_numeric(b):
        raise TypeMismatchError(
            f"Arithmetic requires numeric operands, got {type_of(a)} and {type_of(b)}"
        )
    if op == "/":
        if b == 0:
            return None
        return float(a) / float(b)
    if op == "%":
        if not (isinstance(a, int) and isinstance(b, int)):
            raise TypeMismatchError("% requires two INT operands")
        if b == 0:
            return None
        return a % b
    if op == "+":
        res = a + b
    elif op == "-":
        res = a - b
    elif op == "*":
        res = a * b
    else:
        raise ValueError(f"Unknown arithmetic operator: {op}")
    return float(res) if isinstance(a, float) or isinstance(b, float) else res


def negate(a: object) -> object:
    """Unary arithmetic negation with NULL propagation."""
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"Negate requires numeric operand, got {type_of(a)}")
    return -a

"""Schema definitions for columns and tables."""

from __future__ import annotations

import dataclasses
from microdb.errors import SchemaError

VALID_TYPES = frozenset({"INT", "FLOAT", "TEXT", "BOOL"})


@dataclasses.dataclass(frozen=True)
class Column:
    """Column metadata."""

    name: str
    type: str


def _validate_columns(columns: list[Column]) -> dict[str, int]:
    if not columns:
        raise SchemaError("Table must have at least one column")
    col_map: dict[str, int] = {}
    for idx, col in enumerate(columns):
        if col.name in col_map:
            raise SchemaError(f"Duplicate column name: '{col.name}'")
        if col.type not in VALID_TYPES:
            raise SchemaError(f"Invalid column type: '{col.type}'")
        col_map[col.name] = idx
    return col_map


def _validate_cell(cell: object, expected_type: str, col_name: str) -> object:
    if cell is None:
        return None
    if expected_type == "BOOL":
        if isinstance(cell, bool):
            return cell
        raise SchemaError(f"Column '{col_name}' of type BOOL got {type(cell).__name__}")
    if expected_type == "INT":
        if isinstance(cell, int) and not isinstance(cell, bool):
            return cell
        raise SchemaError(f"Column '{col_name}' of type INT got {type(cell).__name__}")
    if expected_type == "FLOAT":
        if isinstance(cell, (int, float)) and not isinstance(cell, bool):
            return float(cell)
        raise SchemaError(f"Column '{col_name}' of type FLOAT got {type(cell).__name__}")
    if expected_type == "TEXT":
        if isinstance(cell, str):
            return cell
        raise SchemaError(f"Column '{col_name}' of type TEXT got {type(cell).__name__}")
    raise SchemaError(f"Unexpected column type: {expected_type}")


def _validate_rows(columns: list[Column], rows: list[list[object]]) -> list[list[object]]:
    col_count = len(columns)
    validated_rows: list[list[object]] = []
    for row_idx, row in enumerate(rows):
        if len(row) != col_count:
            raise SchemaError(
                f"Row {row_idx} length {len(row)} does not match column count {col_count}"
            )
        new_row = [
            _validate_cell(cell, col.type, col.name)
            for cell, col in zip(row, columns)
        ]
        validated_rows.append(new_row)
    return validated_rows


class Table:
    """Relational table with schema and validated rows."""

    def __init__(
        self, name: str, columns: list[Column], rows: list[list[object]]
    ) -> None:
        self._name: str = name
        self._columns: list[Column] = list(columns)
        self._col_map: dict[str, int] = _validate_columns(self._columns)
        self._rows: list[list[object]] = _validate_rows(self._columns, rows)

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return list(self._columns)

    @property
    def rows(self) -> list[list[object]]:
        return list(self._rows)

    def column_index(self, name: str) -> int:
        """Return 0-based column index or raise SchemaError."""
        if name not in self._col_map:
            raise SchemaError(f"Unknown column: '{name}' in table '{self._name}'")
        return self._col_map[name]

"""Lexer for microdb query language."""

from __future__ import annotations

import dataclasses
from microdb.errors import LexError

KEYWORDS = frozenset({
    "SELECT", "DISTINCT", "FROM", "INNER", "LEFT", "JOIN", "ON",
    "WHERE", "GROUP", "BY", "HAVING", "ORDER", "ASC", "DESC",
    "LIMIT", "OFFSET", "AS", "AND", "OR", "NOT", "IS", "NULL",
    "TRUE", "FALSE"
})


@dataclasses.dataclass(frozen=True)
class Token:
    """Lexical token with source offset."""

    kind: str
    value: object
    offset: int


def _lex_string(query: str, start: int) -> tuple[Token, int]:
    idx = start + 1
    chars: list[str] = []
    n = len(query)
    while idx < n:
        ch = query[idx]
        if ch == "'":
            if idx + 1 < n and query[idx + 1] == "'":
                chars.append("'")
                idx += 2
            else:
                return Token("TEXT", "".join(chars), start), idx + 1
        else:
            chars.append(ch)
            idx += 1
    raise LexError("Unterminated string literal", start)


def _lex_exponent(query: str, idx: int, start: int) -> int:
    n = len(query)
    if idx < n and query[idx] in "eE":
        exp_start = idx
        idx += 1
        if idx < n and query[idx] in "+-":
            idx += 1
        digit_start = idx
        while idx < n and query[idx].isdigit():
            idx += 1
        if idx == digit_start:
            raise LexError("Malformed float exponent", exp_start)
    return idx


def _lex_number(query: str, start: int) -> tuple[Token, int]:
    idx = start
    n = len(query)
    is_float = False
    if query[idx] == ".":
        is_float = True
        idx += 1
        while idx < n and query[idx].isdigit():
            idx += 1
    else:
        while idx < n and query[idx].isdigit():
            idx += 1
        if idx < n and query[idx] == ".":
            is_float = True
            idx += 1
            while idx < n and query[idx].isdigit():
                idx += 1
    exp_idx = _lex_exponent(query, idx, start)
    if exp_idx != idx:
        is_float = True
        idx = exp_idx
    raw = query[start:idx]
    val: object = float(raw) if is_float else int(raw)
    kind = "FLOAT" if is_float else "INT"
    return Token(kind, val, start), idx


def _lex_ident_or_keyword(query: str, start: int) -> tuple[Token, int]:
    idx = start
    n = len(query)
    while idx < n and (query[idx].isalnum() or query[idx] == "_"):
        idx += 1
    text = query[start:idx]
    upper = text.upper()
    if upper in KEYWORDS:
        if upper == "TRUE":
            return Token("BOOL", True, start), idx
        if upper == "FALSE":
            return Token("BOOL", False, start), idx
        if upper == "NULL":
            return Token("NULL", None, start), idx
        return Token("KEYWORD", upper, start), idx
    return Token("IDENT", text, start), idx


def _lex_operator(query: str, start: int) -> tuple[Token, int]:
    n = len(query)
    two = query[start : start + 2]
    if two in ("<>", "<=", ">="):
        return Token("OP", two, start), start + 2
    ch = query[start]
    if ch in "=<>+-*/%(),.":
        return Token("OP", ch, start), start + 1
    raise LexError(f"Unexpected character: {ch!r}", start)


def lex(query: str) -> list[Token]:
    """Tokenize query string into a list of Tokens."""
    tokens: list[Token] = []
    idx = 0
    n = len(query)
    while idx < n:
        ch = query[idx]
        if ch.isspace():
            idx += 1
        elif ch == "-" and idx + 1 < n and query[idx + 1] == "-":
            idx += 2
            while idx < n and query[idx] != "\n":
                idx += 1
        elif ch == "'":
            tok, idx = _lex_string(query, idx)
            tokens.append(tok)
        elif ch.isdigit() or (ch == "." and idx + 1 < n and query[idx + 1].isdigit()):
            tok, idx = _lex_number(query, idx)
            tokens.append(tok)
        elif ch.isalpha() or ch == "_":
            tok, idx = _lex_ident_or_keyword(query, idx)
            tokens.append(tok)
        else:
            tok, idx = _lex_operator(query, idx)
            tokens.append(tok)
    tokens.append(Token("EOF", "", n))
    return tokens

"""Aggregate function evaluation."""

from __future__ import annotations

from microdb.errors import TypeMismatchError, UnknownFunctionError
from microdb.value import compare_lt, is_numeric, type_of

AGGREGATE_NAMES = frozenset({"count", "sum", "avg", "min", "max"})


def is_aggregate_name(name: str) -> bool:
    """Return True if name is a known aggregate function."""
    return name.lower() in AGGREGATE_NAMES


def _eval_sum(non_nulls: list[object]) -> object:
    if not non_nulls:
        return None
    has_float = False
    for v in non_nulls:
        if not is_numeric(v):
            raise TypeMismatchError(f"sum requires numeric input, got {type_of(v)}")
        if isinstance(v, float):
            has_float = True
    total = sum(v for v in non_nulls)  # type: ignore[arg-type]
    return float(total) if has_float else int(total)


def _eval_avg(non_nulls: list[object]) -> object:
    if not non_nulls:
        return None
    for v in non_nulls:
        if not is_numeric(v):
            raise TypeMismatchError(f"avg requires numeric input, got {type_of(v)}")
    total = sum(v for v in non_nulls)  # type: ignore[arg-type]
    return float(total) / len(non_nulls)


def _eval_min_max(non_nulls: list[object], find_min: bool) -> object:
    if not non_nulls:
        return None
    best = non_nulls[0]
    for v in non_nulls[1:]:
        if find_min:
            if compare_lt(v, best) is True:
                best = v
        else:
            if compare_lt(best, v) is True:
                best = v
    return best


def evaluate_aggregate(
    name: str, values: list[object], is_star: bool = False, row_count: int = 0
) -> object:
    """Evaluate an aggregate function over a collection of values."""
    lower_name = name.lower()
    if lower_name == "count":
        if is_star:
            return row_count
        return sum(1 for v in values if v is not None)
    non_nulls = [v for v in values if v is not None]
    if lower_name == "sum":
        return _eval_sum(non_nulls)
    if lower_name == "avg":
        return _eval_avg(non_nulls)
    if lower_name == "min":
        return _eval_min_max(non_nulls, find_min=True)
    if lower_name == "max":
        return _eval_min_max(non_nulls, find_min=False)
    raise UnknownFunctionError(f"Unknown aggregate: '{name}'")

"""Expression AST nodes and evaluation."""

from __future__ import annotations

import dataclasses
from typing import Any, Callable
from microdb.errors import (
    AggregateError,
    ArityError,
    GroupingError,
    TypeMismatchError,
    UnknownFunctionError,
)
from microdb.value import (
    and_,
    arith,
    compare_eq,
    compare_lt,
    is_numeric,
    negate,
    not_,
    or_,
    type_of,
)


@dataclasses.dataclass(frozen=True)
class Expr:
    """Base class for all expression nodes."""


@dataclasses.dataclass(frozen=True)
class Literal(Expr):
    """Literal constant."""

    value: object


@dataclasses.dataclass(frozen=True)
class ColumnRef(Expr):
    """Column reference with optional table qualifier."""

    table: str | None
    column: str


@dataclasses.dataclass(frozen=True)
class UnaryOp(Expr):
    """Unary operator expression."""

    op: str
    operand: Expr


@dataclasses.dataclass(frozen=True)
class BinaryOp(Expr):
    """Binary arithmetic operator expression."""

    op: str
    left: Expr
    right: Expr


@dataclasses.dataclass(frozen=True)
class CompareOp(Expr):
    """Comparison operator expression."""

    op: str
    left: Expr
    right: Expr


@dataclasses.dataclass(frozen=True)
class IsNullOp(Expr):
    """IS NULL / IS NOT NULL predicate."""

    operand: Expr
    negated: bool


@dataclasses.dataclass(frozen=True)
class LogicalOp(Expr):
    """Logical AND / OR expression."""

    op: str
    left: Expr
    right: Expr


@dataclasses.dataclass(frozen=True)
class NotOp(Expr):
    """Logical NOT expression."""

    operand: Expr


@dataclasses.dataclass(frozen=True)
class FunctionCall(Expr):
    """Scalar function call."""

    name: str
    args: list[Expr]


@dataclasses.dataclass(frozen=True)
class AggregateCall(Expr):
    """Aggregate function call."""

    name: str
    arg: Expr | None
    is_star: bool = False


class EvalContext:
    """Abstract evaluation context for expressions."""

    def get_column(self, table: str | None, column: str) -> object:
        raise NotImplementedError

    def get_aggregate(self, call: AggregateCall) -> object:
        raise NotImplementedError

    def matches_group_key(self, expr: Expr) -> tuple[bool, object]:
        return False, None


class RowEvalContext(EvalContext):
    """Context for row-level evaluation (WHERE, ON, un-grouped SELECT)."""

    def __init__(
        self,
        row: list[object],
        resolver: Callable[[str | None, str], int],
    ) -> None:
        self._row: list[object] = row
        self._resolver: Callable[[str | None, str], int] = resolver

    def get_column(self, table: str | None, column: str) -> object:
        idx = self._resolver(table, column)
        return self._row[idx]

    def get_aggregate(self, call: AggregateCall) -> object:
        raise AggregateError(
            f"Aggregate function '{call.name}' is not allowed in this context"
        )


class GroupEvalContext(EvalContext):
    """Context for group-level evaluation (HAVING, grouped SELECT)."""

    def __init__(
        self,
        group_key_values: dict[Expr, object],
        agg_values: dict[AggregateCall, object],
    ) -> None:
        self._group_key_values: dict[Expr, object] = group_key_values
        self._agg_values: dict[AggregateCall, object] = agg_values

    def matches_group_key(self, expr: Expr) -> tuple[bool, object]:
        if expr in self._group_key_values:
            return True, self._group_key_values[expr]
        return False, None

    def get_aggregate(self, call: AggregateCall) -> object:
        if call in self._agg_values:
            return self._agg_values[call]
        raise AggregateError(f"Uncomputed aggregate: {call}")

    def get_column(self, table: str | None, column: str) -> object:
        target = ColumnRef(table, column)
        if target in self._group_key_values:
            return self._group_key_values[target]
        raise GroupingError(
            f"Column '{column}' must appear in the GROUP BY clause or be used in an aggregate function"
        )


def _eval_compare(op: str, l_val: object, r_val: object) -> bool | None:
    if op == "=":
        return compare_eq(l_val, r_val)
    if op == "<>":
        eq = compare_eq(l_val, r_val)
        return not eq if eq is not None else None
    if op == "<":
        return compare_lt(l_val, r_val)
    if op == "<=":
        if l_val is None or r_val is None:
            return None
        return compare_lt(l_val, r_val) or compare_eq(l_val, r_val)
    if op == ">":
        return compare_lt(r_val, l_val)
    if op == ">=":
        if l_val is None or r_val is None:
            return None
        return compare_lt(r_val, l_val) or compare_eq(l_val, r_val)
    raise ValueError(f"Unknown comparison operator: {op}")


def _eval_scalar_text(name: str, args: list[object]) -> object:
    if len(args) != 1:
        raise ArityError(f"Function '{name}' expects 1 argument, got {len(args)}")
    val = args[0]
    if val is None:
        return None
    if not isinstance(val, str):
        raise TypeMismatchError(f"Function '{name}' requires TEXT, got {type_of(val)}")
    if name == "upper":
        return val.upper()
    if name == "lower":
        return val.lower()
    return len(val)


def _eval_scalar_fn(name: str, args: list[object]) -> object:
    lower_name = name.lower()
    if lower_name in ("upper", "lower", "length"):
        return _eval_scalar_text(lower_name, args)
    if lower_name == "abs":
        if len(args) != 1:
            raise ArityError(f"abs expects 1 argument, got {len(args)}")
        val = args[0]
        if val is None:
            return None
        if not is_numeric(val):
            raise TypeMismatchError(f"abs requires numeric argument, got {type_of(val)}")
        return abs(val)  # type: ignore[arg-type]
    if lower_name == "concat":
        if len(args) < 2:
            raise ArityError(f"concat expects at least 2 arguments, got {len(args)}")
        for a in args:
            if a is not None and not isinstance(a, str):
                raise TypeMismatchError(f"concat requires TEXT, got {type_of(a)}")
            if a is None:
                return None
        return "".join(a for a in args)  # type: ignore[arg-type]
    if lower_name == "coalesce":
        if not args:
            raise ArityError("coalesce expects at least 1 argument, got 0")
        for a in args:
            if a is not None:
                return a
        return None
    raise UnknownFunctionError(f"Unknown function: '{name}'")


def eval_expr(expr: Expr, ctx: EvalContext) -> object:
    """Evaluate an expression AST within an evaluation context."""
    matched, val = ctx.matches_group_key(expr)
    if matched:
        return val
    if isinstance(expr, Literal):
        return expr.value
    if isinstance(expr, ColumnRef):
        return ctx.get_column(expr.table, expr.column)
    if isinstance(expr, AggregateCall):
        return ctx.get_aggregate(expr)
    if isinstance(expr, UnaryOp):
        operand_val = eval_expr(expr.operand, ctx)
        if expr.op == "-":
            return negate(operand_val)
        raise ValueError(f"Unknown unary operator: {expr.op}")
    if isinstance(expr, BinaryOp):
        return arith(expr.op, eval_expr(expr.left, ctx), eval_expr(expr.right, ctx))
    if isinstance(expr, CompareOp):
        return _eval_compare(
            expr.op, eval_expr(expr.left, ctx), eval_expr(expr.right, ctx)
        )
    if isinstance(expr, IsNullOp):
        inner_val = eval_expr(expr.operand, ctx)
        return (inner_val is not None) if expr.negated else (inner_val is None)
    if isinstance(expr, LogicalOp):
        l_res = eval_expr(expr.left, ctx)
        r_res = eval_expr(expr.right, ctx)
        return and_(l_res, r_res) if expr.op == "AND" else or_(l_res, r_res)
    if isinstance(expr, NotOp):
        return not_(eval_expr(expr.operand, ctx))
    if isinstance(expr, FunctionCall):
        evaluated_args = [eval_expr(arg, ctx) for arg in expr.args]
        return _eval_scalar_fn(expr.name, evaluated_args)
    raise TypeError(f"Unknown expression node type: {type(expr).__name__}")


def find_aggregates(expr: Expr) -> list[AggregateCall]:
    """Find all AggregateCall nodes in an expression."""
    results: list[AggregateCall] = []

    def _collect(e: Expr) -> None:
        if isinstance(e, AggregateCall):
            results.append(e)
            if e.arg is not None:
                _collect(e.arg)
        elif isinstance(e, (UnaryOp, NotOp, IsNullOp)):
            _collect(e.operand)
        elif isinstance(e, (BinaryOp, CompareOp, LogicalOp)):
            _collect(e.left)
            _collect(e.right)
        elif isinstance(e, FunctionCall):
            for a in e.args:
                _collect(a)

    _collect(expr)
    return results

"""Parser for microdb query language."""

from __future__ import annotations

import dataclasses
import re
from microdb.errors import ParseError
from microdb.expr import (
    AggregateCall,
    BinaryOp,
    ColumnRef,
    CompareOp,
    Expr,
    FunctionCall,
    IsNullOp,
    Literal,
    LogicalOp,
    NotOp,
    UnaryOp,
)
from microdb.lexer import Token, lex


@dataclasses.dataclass(frozen=True)
class SelectItem:
    """A projected item in SELECT."""

    expr: Expr | None
    alias: str | None
    is_star: bool = False
    table_star: str | None = None
    source_text: str = ""


@dataclasses.dataclass(frozen=True)
class JoinClause:
    """JOIN clause specification."""

    type: str  # "INNER" | "LEFT"
    table: str
    on: Expr


@dataclasses.dataclass(frozen=True)
class OrderItem:
    """ORDER BY sort item."""

    expr: Expr
    desc: bool = False


@dataclasses.dataclass(frozen=True)
class Query:
    """Parsed representation of a SELECT statement."""

    distinct: bool
    select_items: list[SelectItem]
    from_table: str
    join: JoinClause | None
    where: Expr | None
    group_by: list[Expr]
    having: Expr | None
    order_by: list[OrderItem]
    limit: int | None
    offset: int | None


class Parser:
    """Recursive-descent parser for microdb SQL."""

    def __init__(self, query_str: str, tokens: list[Token]) -> None:
        self._query_str: str = query_str
        self._tokens: list[Token] = tokens
        self._pos: int = 0
        self._in_aggregate: bool = False

    def _curr(self) -> Token:
        return self._tokens[self._pos]

    def _prev(self) -> Token:
        return self._tokens[self._pos - 1]

    def _peek_offset(self) -> int:
        return self._curr().offset

    def _match_keyword(self, kw: str) -> bool:
        tok = self._curr()
        if tok.kind == "KEYWORD" and tok.value == kw:
            self._pos += 1
            return True
        return False

    def _expect_keyword(self, kw: str) -> None:
        if not self._match_keyword(kw):
            tok = self._curr()
            raise ParseError(f"Expected keyword '{kw}', got {tok.value!r}", tok.offset)

    def _match_op(self, op: str) -> bool:
        tok = self._curr()
        if tok.kind == "OP" and tok.value == op:
            self._pos += 1
            return True
        return False

    def _expect_op(self, op: str) -> None:
        if not self._match_op(op):
            tok = self._curr()
            raise ParseError(f"Expected operator '{op}', got {tok.value!r}", tok.offset)

    def _expect_ident(self, desc: str = "identifier") -> str:
        tok = self._curr()
        if tok.kind == "IDENT":
            self._pos += 1
            return str(tok.value)
        raise ParseError(f"Expected {desc}, got {tok.value!r}", tok.offset)

    def _source_slice(self, start_tok: Token, end_tok: Token) -> str:
        raw = self._query_str[start_tok.offset : end_tok.offset + len(str(end_tok.value))]
        return re.sub(r"\s+", " ", raw).strip()

    def parse(self) -> Query:
        """Parse the full query statement."""
        self._expect_keyword("SELECT")
        distinct = self._match_keyword("DISTINCT")
        items = self._parse_select_items()
        self._expect_keyword("FROM")
        from_table = self._expect_ident("table name")
        join = self._parse_join()
        where = self._parse_where()
        group_by = self._parse_group_by()
        having = self._parse_having()
        order_by = self._parse_order_by()
        limit = self._parse_limit()
        offset = self._parse_offset()
        if self._curr().kind != "EOF":
            tok = self._curr()
            raise ParseError(f"Unexpected token {tok.value!r}", tok.offset)
        return Query(
            distinct=distinct,
            select_items=items,
            from_table=from_table,
            join=join,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _parse_select_items(self) -> list[SelectItem]:
        items: list[SelectItem] = [self._parse_select_item()]
        while self._match_op(","):
            items.append(self._parse_select_item())
        return items

    def _parse_select_item(self) -> SelectItem:
        start_tok = self._curr()
        if self._match_op("*"):
            return SelectItem(
                expr=None, alias=None, is_star=True, table_star=None, source_text="*"
            )
        if (
            start_tok.kind == "IDENT"
            and self._pos + 2 < len(self._tokens)
            and self._tokens[self._pos + 1].kind == "OP"
            and self._tokens[self._pos + 1].value == "."
            and self._tokens[self._pos + 2].kind == "OP"
            and self._tokens[self._pos + 2].value == "*"
        ):
            table = str(start_tok.value)
            self._pos += 3
            return SelectItem(
                expr=None,
                alias=None,
                is_star=False,
                table_star=table,
                source_text=f"{table}.*",
            )
        expr = self._parse_or_expr()
        end_tok = self._prev()
        alias: str | None = None
        if self._match_keyword("AS"):
            alias = self._expect_ident("alias")
        source = self._source_slice(start_tok, end_tok)
        return SelectItem(
            expr=expr,
            alias=alias,
            is_star=False,
            table_star=None,
            source_text=source,
        )

    def _parse_join(self) -> JoinClause | None:
        join_type: str | None = None
        if self._match_keyword("INNER"):
            self._expect_keyword("JOIN")
            join_type = "INNER"
        elif self._match_keyword("LEFT"):
            self._expect_keyword("JOIN")
            join_type = "LEFT"
        elif self._match_keyword("JOIN"):
            join_type = "INNER"
        if join_type is None:
            return None
        table = self._expect_ident("joined table name")
        self._expect_keyword("ON")
        on_expr = self._parse_or_expr()
        return JoinClause(type=join_type, table=table, on=on_expr)

    def _parse_where(self) -> Expr | None:
        if self._match_keyword("WHERE"):
            return self._parse_or_expr()
        return None

    def _parse_group_by(self) -> list[Expr]:
        if not self._match_keyword("GROUP"):
            return []
        self._expect_keyword("BY")
        exprs: list[Expr] = [self._parse_or_expr()]
        while self._match_op(","):
            exprs.append(self._parse_or_expr())
        return exprs

    def _parse_having(self) -> Expr | None:
        if self._match_keyword("HAVING"):
            return self._parse_or_expr()
        return None

    def _parse_order_by(self) -> list[OrderItem]:
        if not self._match_keyword("ORDER"):
            return []
        self._expect_keyword("BY")
        items: list[OrderItem] = [self._parse_order_item()]
        while self._match_op(","):
            items.append(self._parse_order_item())
        return items

    def _parse_order_item(self) -> OrderItem:
        expr = self._parse_or_expr()
        desc = False
        if self._match_keyword("ASC"):
            desc = False
        elif self._match_keyword("DESC"):
            desc = True
        return OrderItem(expr=expr, desc=desc)

    def _parse_limit(self) -> int | None:
        if not self._match_keyword("LIMIT"):
            return None
        tok = self._curr()
        if tok.kind != "INT":
            raise ParseError("LIMIT requires non-negative integer", tok.offset)
        self._pos += 1
        val = int(tok.value)  # type: ignore[arg-type]
        if val < 0:
            raise ParseError("LIMIT must be non-negative", tok.offset)
        return val

    def _parse_offset(self) -> int | None:
        if not self._match_keyword("OFFSET"):
            return None
        tok = self._curr()
        if tok.kind != "INT":
            raise ParseError("OFFSET requires non-negative integer", tok.offset)
        self._pos += 1
        val = int(tok.value)  # type: ignore[arg-type]
        if val < 0:
            raise ParseError("OFFSET must be non-negative", tok.offset)
        return val

    def _parse_or_expr(self) -> Expr:
        expr = self._parse_and_expr()
        while self._match_keyword("OR"):
            right = self._parse_and_expr()
            expr = LogicalOp("OR", expr, right)
        return expr

    def _parse_and_expr(self) -> Expr:
        expr = self._parse_not_expr()
        while self._match_keyword("AND"):
            right = self._parse_not_expr()
            expr = LogicalOp("AND", expr, right)
        return expr

    def _parse_not_expr(self) -> Expr:
        if self._match_keyword("NOT"):
            return NotOp(self._parse_not_expr())
        return self._parse_predicate()

    def _parse_predicate(self) -> Expr:
        left = self._parse_additive()
        tok = self._curr()
        if tok.kind == "OP" and tok.value in ("=", "<>", "<", "<=", ">", ">="):
            op = str(tok.value)
            self._pos += 1
            right = self._parse_additive()
            return CompareOp(op, left, right)
        if self._match_keyword("IS"):
            negated = False
            if self._match_keyword("NOT"):
                negated = True
            tok = self._curr()
            if tok.kind == "NULL":
                self._pos += 1
                return IsNullOp(left, negated)
            raise ParseError(f"Expected NULL after IS, got {tok.value!r}", tok.offset)
        return left

    def _parse_additive(self) -> Expr:
        expr = self._parse_multiplicative()
        while True:
            tok = self._curr()
            if tok.kind == "OP" and tok.value in ("+", "-"):
                self._pos += 1
                right = self._parse_multiplicative()
                expr = BinaryOp(str(tok.value), expr, right)
            else:
                break
        return expr

    def _parse_multiplicative(self) -> Expr:
        expr = self._parse_unary()
        while True:
            tok = self._curr()
            if tok.kind == "OP" and tok.value in ("*", "/", "%"):
                self._pos += 1
                right = self._parse_unary()
                expr = BinaryOp(str(tok.value), expr, right)
            else:
                break
        return expr

    def _parse_unary(self) -> Expr:
        tok = self._curr()
        if tok.kind == "OP" and tok.value == "-":
            self._pos += 1
            return UnaryOp("-", self._parse_unary())
        return self._parse_primary()

    def _parse_aggregate_call(self, name: str, start_tok: Token) -> Expr:
        if self._in_aggregate:
            raise ParseError(f"Aggregates may not nest: {name}", start_tok.offset)
        lower_name = name.lower()
        if lower_name == "count" and self._match_op("*"):
            self._expect_op(")")
            return AggregateCall("count", arg=None, is_star=True)
        self._in_aggregate = True
        try:
            arg = self._parse_or_expr()
        finally:
            self._in_aggregate = False
        self._expect_op(")")
        return AggregateCall(lower_name, arg=arg, is_star=False)

    def _parse_scalar_call(self, name: str) -> Expr:
        args: list[Expr] = []
        if not self._match_op(")"):
            args.append(self._parse_or_expr())
            while self._match_op(","):
                args.append(self._parse_or_expr())
            self._expect_op(")")
        return FunctionCall(name.lower(), args)

    def _parse_ident_primary(self, tok: Token) -> Expr:
        name = str(tok.value)
        if self._match_op("("):
            if name.lower() in ("count", "sum", "avg", "min", "max"):
                return self._parse_aggregate_call(name, tok)
            return self._parse_scalar_call(name)
        if self._match_op("."):
            col_tok = self._curr()
            if col_tok.kind != "IDENT":
                raise ParseError("Expected column name after '.'", col_tok.offset)
            self._pos += 1
            return ColumnRef(table=name, column=str(col_tok.value))
        return ColumnRef(table=None, column=name)

    def _parse_primary(self) -> Expr:
        tok = self._curr()
        if tok.kind in ("INT", "FLOAT", "TEXT", "BOOL", "NULL"):
            self._pos += 1
            return Literal(tok.value)
        if tok.kind == "IDENT":
            self._pos += 1
            return self._parse_ident_primary(tok)
        if self._match_op("("):
            expr = self._parse_or_expr()
            self._expect_op(")")
            return expr
        raise ParseError(f"Unexpected token in expression: {tok.value!r}", tok.offset)


def parse(query_str: str) -> Query:
    """Parse a SQL query string into a Query AST."""
    tokens = lex(query_str)
    return Parser(query_str, tokens).parse()

"""Query planner and plan representation."""

from __future__ import annotations

from collections.abc import Iterator, Sequence
import dataclasses
from typing import Any
from microdb.errors import AggregateError
from microdb.expr import AggregateCall, Expr, Literal, find_aggregates
from microdb.parser import JoinClause, OrderItem, Query, SelectItem


@dataclasses.dataclass(frozen=True)
class Stage:
    """Base stage in a query plan."""

    name: str


@dataclasses.dataclass(frozen=True)
class FromStage(Stage):
    table: str = ""


@dataclasses.dataclass(frozen=True)
class JoinStage(Stage):
    join_type: str = "INNER"
    table: str = ""
    on: Expr = dataclasses.field(default_factory=lambda: Literal(None))


@dataclasses.dataclass(frozen=True)
class WhereStage(Stage):
    predicate: Expr = dataclasses.field(default_factory=lambda: Literal(None))


@dataclasses.dataclass(frozen=True)
class GroupByStage(Stage):
    exprs: list[Expr] = dataclasses.field(default_factory=list)


@dataclasses.dataclass(frozen=True)
class AggregateStage(Stage):
    aggregates: list[AggregateCall] = dataclasses.field(default_factory=list)


@dataclasses.dataclass(frozen=True)
class HavingStage(Stage):
    predicate: Expr = dataclasses.field(default_factory=lambda: Literal(None))


@dataclasses.dataclass(frozen=True)
class SelectStage(Stage):
    items: list[SelectItem] = dataclasses.field(default_factory=list)


@dataclasses.dataclass(frozen=True)
class DistinctStage(Stage):
    pass


@dataclasses.dataclass(frozen=True)
class OrderByStage(Stage):
    items: list[OrderItem] = dataclasses.field(default_factory=list)


@dataclasses.dataclass(frozen=True)
class SliceStage(Stage):
    offset: int | None = None
    limit: int | None = None


class Plan(Sequence[Stage]):
    """Sequence of plan stages."""

    def __init__(self, stages: list[Stage], query: Query) -> None:
        self._stages: list[Stage] = list(stages)
        self.query: Query = query

    def __len__(self) -> int:
        return len(self._stages)

    def __getitem__(self, index: Any) -> Any:
        return self._stages[index]

    def __iter__(self) -> Iterator[Stage]:
        return iter(self._stages)


def _collect_aggregates(query: Query) -> list[AggregateCall]:
    aggs: list[AggregateCall] = []
    for item in query.select_items:
        if item.expr is not None:
            aggs.extend(find_aggregates(item.expr))
    if query.having is not None:
        aggs.extend(find_aggregates(query.having))
    for order in query.order_by:
        aggs.extend(find_aggregates(order.expr))
    return list(dict.fromkeys(aggs))


def plan(query: Query) -> Plan:
    """Construct an execution plan from a parsed Query AST."""
    stages: list[Stage] = [FromStage(name="FROM", table=query.from_table)]
    if query.join is not None:
        if find_aggregates(query.join.on):
            raise AggregateError("ON clause cannot contain aggregate functions")
        stages.append(
            JoinStage(
                name="JOIN",
                join_type=query.join.type,
                table=query.join.table,
                on=query.join.on,
            )
        )
    if query.where is not None:
        if find_aggregates(query.where):
            raise AggregateError("WHERE clause cannot contain aggregate functions")
        stages.append(WhereStage(name="WHERE", predicate=query.where))
    aggs = _collect_aggregates(query)
    if query.group_by or aggs or query.having is not None:
        stages.append(GroupByStage(name="GROUP BY", exprs=query.group_by))
        stages.append(AggregateStage(name="AGGREGATE", aggregates=aggs))
    if query.having is not None:
        stages.append(HavingStage(name="HAVING", predicate=query.having))
    stages.append(SelectStage(name="SELECT", items=query.select_items))
    if query.distinct:
        stages.append(DistinctStage(name="DISTINCT"))
    if query.order_by:
        stages.append(OrderByStage(name="ORDER BY", items=query.order_by))
    if query.offset is not None or query.limit is not None:
        stages.append(
            SliceStage(name="SLICE", offset=query.offset, limit=query.limit)
        )
    return Plan(stages, query)

"""Query execution engine."""

from __future__ import annotations

from collections.abc import Callable
import dataclasses
import functools
from microdb.aggregate import evaluate_aggregate
from microdb.errors import (
    AmbiguousColumnError,
    GroupingError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownTableError,
)
from microdb.expr import (
    AggregateCall,
    ColumnRef,
    EvalContext,
    Expr,
    GroupEvalContext,
    RowEvalContext,
    eval_expr,
)
from microdb.parser import OrderItem, Query, SelectItem
from microdb.planner import Plan
from microdb.schema import Table
from microdb.value import compare_eq, compare_lt


@dataclasses.dataclass(frozen=True)
class Result:
    """Query result containing column names and rows."""

    columns: list[str]
    rows: list[list[object]]


def _make_resolver(
    cols: list[tuple[str, str]],
) -> Callable[[str | None, str], int]:
    def resolve(table: str | None, column: str) -> int:
        if table is not None:
            known_tables = {tbl for tbl, _ in cols}
            if table not in known_tables:
                raise UnknownTableError(f"Unknown table '{table}'")
            matches = [
                i for i, (tbl, c) in enumerate(cols) if tbl == table and c == column
            ]
            if not matches:
                raise UnknownColumnError(f"Unknown column '{table}.{column}'")
            return matches[0]
        matches = [i for i, (_, c) in enumerate(cols) if c == column]
        if len(matches) > 1:
            raise AmbiguousColumnError(f"Ambiguous column '{column}'")
        if not matches:
            raise UnknownColumnError(f"Unknown column '{column}'")
        return matches[0]

    return resolve


def _exec_join(
    left_cols: list[tuple[str, str]],
    left_rows: list[list[object]],
    join_type: str,
    t2: Table,
    t2_name: str,
    on_expr: Expr,
) -> tuple[list[tuple[str, str]], list[list[object]]]:
    right_cols = [(t2_name, col.name) for col in t2.columns]
    combined_cols = left_cols + right_cols
    resolver = _make_resolver(combined_cols)
    out_rows: list[list[object]] = []
    right_nulls = [None] * len(t2.columns)
    for l_row in left_rows:
        matched = False
        for r_row in t2.rows:
            cand = l_row + r_row
            pred = eval_expr(on_expr, RowEvalContext(cand, resolver))
            if pred is not None and not isinstance(pred, bool):
                raise TypeMismatchError("ON predicate must be boolean")
            if pred is True:
                out_rows.append(cand)
                matched = True
        if join_type == "LEFT" and not matched:
            out_rows.append(l_row + right_nulls)
    return combined_cols, out_rows


def _exec_from_and_join(
    query: Query, tables: dict[str, Table]
) -> tuple[list[tuple[str, str]], list[list[object]]]:
    t1_name = query.from_table
    if t1_name not in tables:
        raise UnknownTableError(f"Unknown table '{t1_name}'")
    t1 = tables[t1_name]
    cols = [(t1_name, col.name) for col in t1.columns]
    rows = [list(r) for r in t1.rows]
    if query.join is not None:
        t2_name = query.join.table
        if t2_name not in tables:
            raise UnknownTableError(f"Unknown table '{t2_name}'")
        cols, rows = _exec_join(
            cols, rows, query.join.type, tables[t2_name], t2_name, query.join.on
        )
    return cols, rows


def _exec_where(
    where_expr: Expr | None,
    cols: list[tuple[str, str]],
    rows: list[list[object]],
) -> list[list[object]]:
    if where_expr is None:
        return rows
    resolver = _make_resolver(cols)
    filtered: list[list[object]] = []
    for row in rows:
        pred = eval_expr(where_expr, RowEvalContext(row, resolver))
        if pred is not None and not isinstance(pred, bool):
            raise TypeMismatchError("WHERE predicate must be boolean")
        if pred is True:
            filtered.append(row)
    return filtered


def _cell_group_equal(a: object, b: object) -> bool:
    if a is None and b is None:
        return True
    if a is None or b is None:
        return False
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    return compare_eq(a, b) is True


def _key_equal(k1: tuple[object, ...], k2: tuple[object, ...]) -> bool:
    return len(k1) == len(k2) and all(
        _cell_group_equal(a, b) for a, b in zip(k1, k2)
    )


def _eval_group_aggregates(
    aggs: list[AggregateCall],
    g_rows: list[list[object]],
    resolver: Callable[[str | None, str], int],
) -> dict[AggregateCall, object]:
    agg_values: dict[AggregateCall, object] = {}
    row_count = len(g_rows)
    for call in aggs:
        if call.is_star:
            val = evaluate_aggregate(call.name, [], is_star=True, row_count=row_count)
        else:
            evaluated = [
                eval_expr(call.arg, RowEvalContext(r, resolver))  # type: ignore[arg-type]
                for r in g_rows
            ]
            val = evaluate_aggregate(
                call.name, evaluated, is_star=False, row_count=row_count
            )
        agg_values[call] = val
    return agg_values


def _exec_group_by_and_aggregate(
    query: Query,
    cols: list[tuple[str, str]],
    rows: list[list[object]],
    aggs: list[AggregateCall],
) -> list[GroupEvalContext]:
    resolver = _make_resolver(cols)
    groups: list[tuple[tuple[object, ...], list[list[object]]]] = []
    if query.group_by:
        for row in rows:
            key = tuple(
                eval_expr(e, RowEvalContext(row, resolver)) for e in query.group_by
            )
            found = False
            for g_key, g_rows in groups:
                if _key_equal(g_key, key):
                    g_rows.append(row)
                    found = True
                    break
            if not found:
                groups.append((key, [row]))
    else:
        groups.append(((), rows))
    contexts: list[GroupEvalContext] = []
    for g_key, g_rows in groups:
        agg_values = _eval_group_aggregates(aggs, g_rows, resolver)
        group_key_map = dict(zip(query.group_by, g_key))
        contexts.append(GroupEvalContext(group_key_map, agg_values))
    return contexts


def _exec_having(
    having_expr: Expr | None, contexts: list[GroupEvalContext]
) -> list[GroupEvalContext]:
    if having_expr is None:
        return contexts
    surviving: list[GroupEvalContext] = []
    for ctx in contexts:
        pred = eval_expr(having_expr, ctx)
        if pred is not None and not isinstance(pred, bool):
            raise TypeMismatchError("HAVING predicate must be boolean")
        if pred is True:
            surviving.append(ctx)
    return surviving


def _expand_select_items(
    items: list[SelectItem],
    cols: list[tuple[str, str]],
) -> list[tuple[Expr, str, str | None]]:
    expanded: list[tuple[Expr, str, str | None]] = []
    for item in items:
        if item.is_star:
            for tbl, col_name in cols:
                expanded.append((ColumnRef(tbl, col_name), col_name, None))
        elif item.table_star is not None:
            tbl_match = [c for t, c in cols if t == item.table_star]
            if not tbl_match:
                raise UnknownTableError(f"Unknown table '{item.table_star}'")
            for col_name in tbl_match:
                expanded.append(
                    (ColumnRef(item.table_star, col_name), col_name, None)
                )
        else:
            expr = item.expr
            assert expr is not None
            if item.alias is not None:
                name = item.alias
            elif isinstance(expr, ColumnRef) and expr.table is None:
                name = expr.column
            else:
                name = item.source_text
            expanded.append((expr, name, item.alias))
    return expanded


def _project_rows(
    expanded: list[tuple[Expr, str, str | None]],
    contexts: list[EvalContext],
) -> list[tuple[list[object], EvalContext]]:
    projected: list[tuple[list[object], EvalContext]] = []
    for ctx in contexts:
        row_vals = [eval_expr(expr, ctx) for expr, _, _ in expanded]
        projected.append((row_vals, ctx))
    return projected


def _exec_distinct(
    rows: list[tuple[list[object], EvalContext]],
) -> list[tuple[list[object], EvalContext]]:
    unique_rows: list[tuple[list[object], EvalContext]] = []
    for row_vals, ctx in rows:
        key = tuple(row_vals)
        if not any(_key_equal(key, tuple(existing[0])) for existing in unique_rows):
            unique_rows.append((row_vals, ctx))
    return unique_rows


class _OrderByContext(EvalContext):
    def __init__(
        self,
        output_row: list[object],
        alias_map: dict[str, int],
        base_ctx: EvalContext | None,
    ) -> None:
        self._output_row: list[object] = output_row
        self._alias_map: dict[str, int] = alias_map
        self._base_ctx: EvalContext | None = base_ctx

    def get_column(self, table: str | None, column: str) -> object:
        if table is None and column in self._alias_map:
            return self._output_row[self._alias_map[column]]
        if self._base_ctx is not None:
            return self._base_ctx.get_column(table, column)
        raise UnknownColumnError(f"Unknown column: '{column}'")

    def get_aggregate(self, call: AggregateCall) -> object:
        if self._base_ctx is not None:
            return self._base_ctx.get_aggregate(call)
        raise UnknownColumnError(f"Unknown aggregate in ORDER BY: {call.name}")

    def matches_group_key(self, expr: Expr) -> tuple[bool, object]:
        if self._base_ctx is not None:
            return self._base_ctx.matches_group_key(expr)
        return False, None


def _compare_sort_values(v1: object, v2: object, desc: bool) -> int:
    if v1 is None and v2 is None:
        return 0
    if v1 is None:
        return 1
    if v2 is None:
        return -1
    eq = compare_eq(v1, v2)
    if eq is True:
        return 0
    lt = compare_lt(v1, v2)
    if desc:
        return -1 if not lt else 1
    return -1 if lt else 1


def _sort_rows(
    rows: list[tuple[list[object], EvalContext]],
    order_items: list[OrderItem],
    alias_map: dict[str, int],
    is_distinct: bool,
) -> list[tuple[list[object], EvalContext]]:
    evaluated_orders: list[tuple[tuple[object, ...], tuple[list[object], EvalContext]]] = []
    for row_vals, ctx in rows:
        ob_ctx = _OrderByContext(
            row_vals, alias_map, None if is_distinct else ctx
        )
        keys = tuple(eval_expr(item.expr, ob_ctx) for item in order_items)
        evaluated_orders.append((keys, (row_vals, ctx)))

    def _cmp_rows(
        item1: tuple[tuple[object, ...], tuple[list[object], EvalContext]],
        item2: tuple[tuple[object, ...], tuple[list[object], EvalContext]],
    ) -> int:
        for (v1, v2), oi in zip(zip(item1[0], item2[0]), order_items):
            cmp = _compare_sort_values(v1, v2, oi.desc)
            if cmp != 0:
                return cmp
        return 0

    sorted_items = sorted(evaluated_orders, key=functools.cmp_to_key(_cmp_rows))
    return [item[1] for item in sorted_items]


def _exec_order_by(
    rows: list[tuple[list[object], EvalContext]],
    order_items: list[OrderItem],
    output_names: list[str],
    aliases: dict[str, int],
    is_distinct: bool,
) -> list[tuple[list[object], EvalContext]]:
    if not order_items:
        return rows
    alias_map = (
        {name: i for i, name in enumerate(output_names)}
        if is_distinct
        else aliases
    )
    return _sort_rows(rows, order_items, alias_map, is_distinct)


def _exec_slice(
    rows: list[list[object]], offset: int | None, limit: int | None
) -> list[list[object]]:
    if offset is not None:
        rows = rows[offset:]
    if limit is not None:
        rows = rows[:limit]
    return rows


def execute_plan(plan: Plan, tables: dict[str, Table]) -> Result:
    """Execute a planned query against a dictionary of tables."""
    query = plan.query
    cols, rows = _exec_from_and_join(query, tables)
    rows = _exec_where(query.where, cols, rows)
    expanded = _expand_select_items(query.select_items, cols)
    output_names = [name for _, name, _ in expanded]
    aliases = {alias: i for i, (_, _, alias) in enumerate(expanded) if alias is not None}
    aggs = [stage.aggregates for stage in plan if stage.name == "AGGREGATE"]
    is_grouped = bool(aggs) or bool(query.group_by) or query.having is not None
    if is_grouped:
        flattened_aggs = aggs[0] if aggs else []
        contexts = _exec_group_by_and_aggregate(query, cols, rows, flattened_aggs)
        contexts = _exec_having(query.having, contexts)  # type: ignore[assignment]
        eval_contexts: list[EvalContext] = contexts  # type: ignore[assignment]
    else:
        resolver = _make_resolver(cols)
        eval_contexts = [RowEvalContext(r, resolver) for r in rows]
    proj_rows = _project_rows(expanded, eval_contexts)
    if query.distinct:
        proj_rows = _exec_distinct(proj_rows)
    if query.order_by:
        proj_rows = _exec_order_by(
            proj_rows, query.order_by, output_names, aliases, query.distinct
        )
    raw_rows = [vals for vals, _ in proj_rows]
    raw_rows = _exec_slice(raw_rows, query.offset, query.limit)
    return Result(columns=output_names, rows=raw_rows)

